// Accepts either:
//  - a single job object (from the Webhook body)
//  - { "jobs": [...] } (a wrapped list)
//  - a raw array (from data/latest_jobs.json)
// and always returns one n8n item per job.
let payload = $input.first().json;

if (payload.body) {
  payload = payload.body;
}

let jobs;
if (Array.isArray(payload)) {
  jobs = payload;
} else if (Array.isArray(payload.jobs)) {
  jobs = payload.jobs;
} else {
  jobs = [payload];
}

return jobs.map((job) => ({ json: job }));

const j = $json;
const hot = (j.score >= 90) ? '🚨🚨 HOT JOB 🚨🚨
' : '';
const tech = (j.technical_matches || []).slice(0, 10).map(t => `✅ ${t}`).join('
');
const transfer = (j.transferable_matches || []).slice(0, 6).map(t => `• ${t}`).join('
');
const text = `${hot}${j.priority || ''} ${j.score}/100

` +
  `<b>${j.title || ''}</b>
${j.company || ''}

` +
  `🌍 Remote: ${j.remote ? 'Yes' : (j.location || 'Unspecified')}
` +
  `💰 ${j.salary || 'Not listed'}
` +
  `📍 Source: ${j.source || ''}

` +
  (tech ? `<b>WHY IT MATCHES</b>
${tech}

` : '') +
  (transfer ? `<b>🔄 TRANSFERABLE</b>
${transfer}

` : '') +
  `Reason: ${j.reason || ''}

` +
  `👉 <a href="${j.url}">APPLY</a>`;
return [{ json: { ...j, telegram_text: text } }];
